<?php require 'faculty_bootstrap.php';$title='Announcements';$fid=(int)$_SESSION['user']['id'];$pdo->exec("CREATE TABLE IF NOT EXISTS announcements(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,type ENUM('General','Important','Event') DEFAULT 'General',author_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");$cols=$pdo->query('SHOW COLUMNS FROM announcements')->fetchAll(PDO::FETCH_COLUMN,0);if(!in_array('target_subject_id',$cols,true)){$pdo->exec('ALTER TABLE announcements ADD COLUMN target_subject_id INT NULL');}
$subs=$pdo->prepare("SELECT DISTINCT s.id,s.code,s.name FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id WHERE o.faculty_id=? ORDER BY s.code");$subs->execute([$fid]);$subs=$subs->fetchAll();$q=$pdo->prepare("SELECT a.*,s.code subject_code,s.name subject_name FROM announcements a LEFT JOIN subjects s ON s.id=a.target_subject_id WHERE a.author_id=? ORDER BY a.created_at DESC");$q->execute([$fid]);$mine=$q->fetchAll();require 'header.php';faculty_flash_html();
?><section class="section"><div class="section-intro"><div><span class="eyebrow">COMMUNICATIONS</span><h2>Announcement Management</h2><p class="muted">Publish updates to all students or only students enrolled in one of your classes.</p></div></div><form method="post" class="faculty-announcement-form"><?=faculty_form_return('faculty_announcements.php')?><input type="hidden" name="action" value="faculty_publish_announcement"><div class="register-grid"><div class="field"><label>Announcement Title</label><input name="announcement_title" placeholder="Announcement title" required></div><div class="field"><label>Type</label><select name="announcement_type"><option>General</option><option>Important</option><option>Event</option></select></div><div class="field"><label>Audience</label><select name="subject_id"><option value="0">All active students</option><?php foreach($subs as $s):?><option value="<?=$s['id']?>"><?=e($s['code'].' — '.$s['name'])?></option><?php endforeach;?></select></div><div class="field field-full"><label>Announcement Message</label><textarea name="announcement_body" rows="5" placeholder="Write your announcement..." required></textarea></div></div><button class="btn">Publish Announcement</button></form></section><section class="section"><div class="card-head"><h2>My Published Announcements</h2><span class="muted"><?=count($mine)?> announcements</span></div><?php if(!$mine):?><p class="muted">You have not published any announcements yet.</p><?php endif;?><?php foreach($mine as $a):?><div class="announcement"><div class="card-head"><div><b><?=e($a['title'])?></b><small class="muted">Published <?=date('M d, Y · g:i A',strtotime($a['created_at']))?><?php if($a['subject_code']):?> · <?=e($a['subject_code'])?><?php else:?> · All active students<?php endif;?></small></div><span class="badge"><?=e($a['type'])?></span></div><p><?=nl2br(e($a['body']))?></p><form method="post" class="inline-form"><?=faculty_form_return('faculty_announcements.php')?><input type="hidden" name="action" value="faculty_delete_announcement"><input type="hidden" name="announcement_id" value="<?=$a['id']?>"><button class="btn danger-btn">Delete</button></form></div><?php endforeach;?></section><?php require 'footer.php';?>
